mapper.select:
SELECT
count(*)
FROM
`attendance_group_staff` ags
LEFT JOIN `attendance_group` ag ON ags.`group_id` = ag.`id`
WHERE
ags.`staff_id` IN

    #{item}

AND ag.`type` = #{groupType}

    AND ag.`id`  <>  #{groupId}

SELECT ag.`id` AS `groupId`, ags.`staff_id` FROM `attendance_group_staff` ags LEFT JOIN `attendance_group` ag ON ags.`group_id` = ag.`id` WHERE ags.`staff_id` IN
#{item}
AND ag.`type` = #{groupType}

SELECT
ags.`group_id`
FROM
`attendance_group_staff` ags
LEFT JOIN `attendance_group` ag ON ags.`group_id` = ag.`id`
WHERE
ags.`staff_id` = #{staffId}

    AND ag.`type` = #{groupType}


    AND ags.`group_id`  <>  #{groupId}

SELECT ags.`staff_id` FROM `attendance_group_staff` ags LEFT JOIN `attendance_group` ag ON ags.`group_id` = ag.`id`
ag.`type` = #{groupType}
AND ags.`group_id` <> #{groupId}

select DISTINCT aw.`staff_id`, aw.`staff_name`, aw.`staff_mobile`, aw.`staff_organization_id`, aw.`group_id` from `arrange_work` aw WHERE aw.`deleted` = 0
AND aw.`group_id` = #{param.groupId}
AND aw.`staff_organization_id` = #{param.organizationId}
AND aw.`month` = #{param.month}
AND aw.`staff_name` like CONCAT('%',#{param.staffName},'%')
group by aw.`staff_id` order by aw.`staff_id`
